            if near:
                allc=mcells+[(scc,mc)]  # mark which is marker
                rs=[r for r,_ in allc]; cls=[c for _,c in allc]
                h=max(rs)-min(rs)+1; w=max(cls)-min(cls)+1
                for mode,paint in [('keepbg',bg),('paint',mc)]:
                    res=[[paint]*w for _ in range(h)]
                    for (r,c,tag) in allc:
                        if tag!=mc: continue
                        res[r-min(rs)][c-min(cls)]=paint
                    if mode=='keepbg':
                        res[scc[0]-min(rs)][scc[1]-min(cls)]=bg
                    if res==out: sols.append((mode,'paint' if False else ('marker' if tag==scc else 'comp'),paint))
