                            if 0<=a<H and 0<=b<W and g[a][b]!=bg and (a,b) not in seen:
                                seen.add((a,b)); q.append((a,b))
                comps.append(cells)
    cnt=Counter(r*W+c for r,c in sum(comps,[]))
    # marker = smallest component containing fewest distinct colors? take min-size comp whose cells are minority colors
    best=None
    for cl in sorted(comps,key=len):
